//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");


//ESG채권 처리자 조회
scwin.vScrenID = "ULDBNS22004.xml";
scwin.param1 = "";
scwin.STD_CD_APPL_ID = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : ESG채권 처리자 조회
 ***********************************************/
scwin.ins_search = function() {
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var param = '';
    param += "&{P}STD_CD=" + scwin.param1; //표준코드

    var dsNm = 'BNSSRI_PRCNM_LIST';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtList.prcnm';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = scwin.STD_CD_APPL_ID;
    scwin.arrPar[1] = "STD_CD";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(scwin.arrPar);
        scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] != undefined) ? scwin.arrPar[0] : "");
        //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

        scwin.ins_search();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    $c.stf.alert_error(dts_List);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    //alert('dts_List.OnLoadCompleted('+rowcount+')');

};
